response:
{
  "title": "Invoice processing",
  "summary": "Process inbound invoice emails every morning by downloading PDFs, logging them in a Google Sheet, and notifying accounting, with manager sign-off for large invoices.",
  "trigger": {
    "kind": "schedule",
    "description": "Every morning I go through my emails looking for invoices.",
    "first_step_id": "check_emails",
    "schedule_hint": "every weekday morning",
    "system_id": "email_client"
  },
  "steps": [
    {
      "id": "check_emails",
      "name": "Check emails for invoices",
      "description": "Open email and scan through to find incoming invoices.",
      "kind": "read",
      "assumption": "The user reviews emails in an email client like Gmail or Outlook.",
      "outputs": [
        {
          "name": "invoice_email",
          "data_type": "record",
          "contains_personal_data": true,
          "description": "An email containing an invoice attachment."
        }
      ],
      "system_id": "email_client"
    },
    {
      "id": "download_pdf",
      "name": "Download the PDF attachment",
      "description": "Save the PDF attachment from the invoice email.",
      "kind": "write",
      "iterates_over": "each PDF attachment on the email",
      "outputs": [
        {
          "name": "invoice_pdf",
          "data_type": "file",
          "contains_personal_data": false,
          "description": "The downloaded invoice PDF file."
        }
      ],
      "system_id": "email_client"
    },
    {
      "id": "read_total",
      "name": "Read the total off the PDF",
      "description": "Look at the invoice PDF to find the total amount due.",
      "kind": "extract",
      "inputs": [
        {
          "name": "invoice_pdf",
          "data_type": "file",
          "contains_personal_data": false
        }
      ],
      "outputs": [
        {
          "name": "invoice_total",
          "data_type": "money",
          "contains_personal_data": false,
          "description": "The total amount on the invoice."
        }
      ]
    },
    {
      "id": "check_amount_size",
      "name": "Check if invoice is over five thousand pounds",
      "description": "Determine whether the invoice total is greater than £5,000.",
      "kind": "decision",
      "inputs": [
        {
          "name": "invoice_total",
          "data_type": "money",
          "contains_personal_data": false
        }
      ],
      "outputs": [
        {
          "name": "invoice_total",
          "data_type": "money",
          "contains_personal_data": false
        }
      ]
    },
    {
      "id": "manager_check",
      "name": "Check with manager",
      "description": "Ask the manager for approval before putting the invoice through.",
      "kind": "judgement",
      "inputs": [
        {
          "name": "invoice_total",
          "data_type": "money",
          "contains_personal_data": false
        }
      ],
      "outputs": [
        {
          "name": "approval_status",
          "data_type": "boolean",
          "contains_personal_data": false,
          "description": "Manager sign-off decision."
        }
      ]
    },
    {
      "id": "enter_into_sheet",
      "name": "Type total into Google Sheet",
      "description": "Enter the invoice total into the company Google Sheet.",
      "kind": "write",
      "inputs": [
        {
          "name": "invoice_total",
          "data_type": "money",
          "contains_personal_data": false
        }
      ],
      "outputs": [
        {
          "name": "sheet_entry",
          "data_type": "record",
          "contains_personal_data": false,
          "description": "The recorded entry in the spreadsheet."
        }
      ],
      "system_id": "google_sheets"
    },
    {
      "id": "notify_accounting",
      "name": "Message accounting on Slack",
      "description": "Send a message to accounting to let them know the invoice is in.",
      "kind": "notify",
      "system_id": "slack"
    }
  ],
  "edges": [
    {
      "from_step": "check_emails",
      "to_step": "download_pdf"
    },
    {
      "from_step": "download_pdf",
      "to_step": "read_total"
    },
    {
      "from_step": "read_total",
      "to_step": "check_amount_size"
    },
    {
      "from_step": "check_amount_size",
      "to_step": "manager_check",
      "condition": "amount is over five thousand pounds",
      "condition_test": {
        "field": "invoice_total",
        "operator": "gt",
        "currency": "GBP",
        "value": "5000",
        "value_type": "money"
      }
    },
    {
      "from_step": "check_amount_size",
      "to_step": "enter_into_sheet",
      "condition": "amount is five thousand pounds or less",
      "condition_test": {
        "field": "invoice_total",
        "operator": "lte",
        "currency": "GBP",
        "value": "5000",
        "value_type": "money"
      }
    },
    {
      "from_step": "manager_check",
      "to_step": "enter_into_sheet"
    },
    {
      "from_step": "enter_into_sheet",
      "to_step": "notify_accounting"
    }
  ],
  "systems": [
    {
      "id": "email_client",
      "name": "Email",
      "category": "email",
      "notes": "Used to receive and review invoice emails."
    },
    {
      "id": "google_sheets",
      "name": "Google Sheet",
      "category": "spreadsheet",
      "notes": "Used to log invoice totals manually."
    },
    {
      "id": "slack",
      "name": "Slack",
      "category": "chat",
      "notes": "Used to notify accounting."
    }
  ]
}
